import{_ as o,o as t,c as r,a1 as a}from"./chunks/framework.DceXOx8u.js";const p=JSON.parse('{"title":"Going to production","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://andresayac.github.io/botmesh/guide/production"}],["meta",{"property":"og:url","content":"https://andresayac.github.io/botmesh/guide/production"}]]},"headers":[],"relativePath":"guide/production.md","filePath":"guide/production.md"}'),s={name:"guide/production.md"};function d(i,e,c,n,h,l){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="going-to-production" tabindex="-1">Going to production <a class="header-anchor" href="#going-to-production" aria-label="Permalink to &quot;Going to production&quot;">​</a></h1><p>A checklist for taking a bot from &quot;works on my machine&quot; to a deployment you can leave running. Each item links to the page with the details. Work through <strong>Every bot</strong> first; the later sections only apply when you need them.</p><h2 id="every-bot" tabindex="-1">Every bot <a class="header-anchor" href="#every-bot" aria-label="Permalink to &quot;Every bot&quot;">​</a></h2><h3 id="runtime" tabindex="-1">Runtime <a class="header-anchor" href="#runtime" aria-label="Permalink to &quot;Runtime&quot;">​</a></h3><ul><li><strong>Node.js 22 or later</strong>, and your app is ESM (<code>&quot;type&quot;: &quot;module&quot;</code> in <code>package.json</code>, or <code>.mjs</code> files). The packages ship no CommonJS build.</li><li><strong>A process manager</strong> restarts the bot when it exits: PM2, systemd, Docker <code>restart: unless-stopped</code> or your orchestrator. See <a href="./deploy">Deployment</a>.</li><li><strong>Graceful shutdown</strong>: on <code>SIGTERM</code>/<code>SIGINT</code> call <code>await bot.stop({ drain: true, timeout: &#39;15s&#39; })</code> so replies in flight are sent and recorded before the process exits (<a href="./deploy#graceful-shutdown">Graceful shutdown</a>).</li><li><strong>Pin your versions</strong> (commit the lockfile). While the packages are in beta, read the <a href="./stable-migration">migration pages</a> before each upgrade.</li></ul><h3 id="state" tabindex="-1">State <a class="header-anchor" href="#state" aria-label="Permalink to &quot;State&quot;">​</a></h3><ul><li><strong>A persistent store.</strong> The default <code>MemoryStore</code> keeps everything in RAM. Use <code>SQLiteStore</code> for one process or <code>RedisStore</code> for several (<a href="./store#choosing-a-store">Persistent store</a>).</li><li>Pass the store <strong>instance</strong>: <code>store: new SQLiteStore({ file })</code>. A string such as <code>store: &#39;sqlite&#39;</code> is accepted for compatibility but still creates a <code>MemoryStore</code>.</li><li><strong>Multi-step flows are <code>.persistent()</code></strong>, so a user in the middle of a flow resumes it after a restart (<a href="./flows">Flows</a>).</li><li><strong>On Node.js 24.19 or later, use <code>better-sqlite3</code> 13</strong> with <code>SQLiteStore</code> (<a href="./store#sqlitestore">why</a>).</li><li><strong>Volumes and backups</strong>: the WhatsApp session folder (<code>sessions/</code>) and the data folder (<code>data/</code>) are mounted on persistent disk and backed up together (<a href="./deploy#backups">Backups</a>).</li></ul><h3 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h3><ul><li>Tokens, API keys and webhook secrets come from the environment (or your secret manager), never from the source tree. The framework reads no environment variable by itself: you map them to the provider options (<a href="./deploy#environment-variables">Environment variables</a>).</li><li><code>sessions/</code>, <code>.env</code>, <code>*.db</code> and <code>*.qr.png</code> are in <code>.gitignore</code> and never copied into a Docker image.</li></ul><h3 id="webhooks-cloud-api-telegram-webhook-twilio" tabindex="-1">Webhooks (Cloud API, Telegram webhook, Twilio…) <a class="header-anchor" href="#webhooks-cloud-api-telegram-webhook-twilio" aria-label="Permalink to &quot;Webhooks (Cloud API, Telegram webhook, Twilio…)&quot;">​</a></h3><ul><li>Served over <strong>HTTPS</strong>, with the channel&#39;s signature check configured (<code>appSecret</code>, <code>webhookSecret</code>…). Never set <code>allowUnsignedWebhooks: true</code> in production (<a href="./security#production-checklist">Security</a>).</li><li>The signature is checked on the <strong>raw body</strong>: do not put a JSON body parser in front of the webhook route (<a href="./server">Webhook server</a>).</li></ul><h3 id="observability" tabindex="-1">Observability <a class="header-anchor" href="#observability" aria-label="Permalink to &quot;Observability&quot;">​</a></h3><ul><li><strong>Logs</strong>: pass your own pino <code>logger</code> (or keep the built-in one, which logs at <code>warn</code>). Chat and sender ids are hashed in log lines by default (<code>logIds: &#39;hash&#39;</code>); keep it that way outside local debugging.</li><li><strong>Errors</strong>: listen to <code>bot.on(&#39;error&#39;, …)</code> and send them to your error tracker.</li><li><strong>Health and metrics</strong>: expose a liveness/readiness endpoint and <code>bot.metrics()</code> in Prometheus format (<a href="./deploy#health-checks">Health checks</a>, <a href="./operations#runtime-metrics">Operations</a>).</li></ul><h3 id="channel-limits" tabindex="-1">Channel limits <a class="header-anchor" href="#channel-limits" aria-label="Permalink to &quot;Channel limits&quot;">​</a></h3><ul><li><strong>WhatsApp on Baileys</strong>: keep the provider&#39;s rate limiter on and avoid unsolicited bulk sends (<a href="./rate-limiting">Rate limiting</a>).</li><li><strong>Cloud API</strong>: free-form replies only within the 24-hour window; use templates outside it (<a href="./session-window">WhatsApp 24h window</a>).</li><li><strong>Message log growth</strong>: the persistent stores keep every message unless you set <code>maxMessagesPerChat</code> (<a href="./store#sqlitestore">Persistent store</a>).</li></ul><h2 id="when-you-need-more" tabindex="-1">When you need more <a class="header-anchor" href="#when-you-need-more" aria-label="Permalink to &quot;When you need more&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You need…</th><th>Turn on</th><th>Guide</th></tr></thead><tbody><tr><td>No lost or duplicated replies when the process crashes mid-message</td><td><code>BotConfig.durability</code> with a persistent backend</td><td><a href="./durability">Durable message processing</a></td></tr><tr><td>Reminders and reports that survive restarts and run once with several replicas</td><td>Durable tasks (<code>{ id }</code>) + <code>BotConfig.scheduler</code></td><td><a href="./scheduler#durable-tasks-survive-restarts-one-replica-per-run">Scheduler</a></td></tr><tr><td>Several processes of one bot (failover, rolling deploys, webhook throughput)</td><td><code>BotConfig.coordination</code> + <code>RedisStore</code></td><td><a href="./replicas">Running N replicas</a></td></tr><tr><td>Redis Cluster instead of a single Redis</td><td>The <code>&#39;cluster&#39;</code> key layout</td><td><a href="./redis-cluster">Redis Cluster</a></td></tr><tr><td>Where the time goes in each message</td><td><code>BotConfig.telemetry</code></td><td><a href="./tracing">Tracing</a></td></tr></tbody></table><p>All of these are opt-in: without the option, the bot runs exactly as before.</p><h2 id="which-packages-are-published" tabindex="-1">Which packages are published <a class="header-anchor" href="#which-packages-are-published" aria-label="Permalink to &quot;Which packages are published&quot;">​</a></h2><p>The npm packages (36) are <code>@botmesh/core</code>; the channels <code>@botmesh/baileys</code>, <code>@botmesh/meta</code>, <code>@botmesh/telegram</code>, <code>@botmesh/messenger</code>, <code>@botmesh/instagram</code>, <code>@botmesh/discord</code>, <code>@botmesh/evolution</code>, <code>@botmesh/wppconnect</code>, <code>@botmesh/twilio</code>, <code>@botmesh/gupshup</code>, <code>@botmesh/gohighlevel</code> and <code>@botmesh/email</code>; the stores <code>@botmesh/sqlite-store</code>, <code>@botmesh/redis-store</code>, <code>@botmesh/postgres-store</code>, <code>@botmesh/mysql-store</code> and <code>@botmesh/mongo-store</code>; the infrastructure <code>@botmesh/http</code>, <code>@botmesh/graph-core</code>, <code>@botmesh/wa-gateway-kit</code>, <code>@botmesh/server</code>, <code>@botmesh/events</code> and <code>@botmesh/otel</code>; the plugins <code>@botmesh/ai</code>, <code>@botmesh/rag</code>, <code>@botmesh/voice</code>, <code>@botmesh/nlu</code>, <code>@botmesh/dialogflow</code>, <code>@botmesh/chatwoot</code>, <code>@botmesh/tickets</code> and <code>@botmesh/moderation</code>; and the tooling <code>@botmesh/flow-schema</code>, <code>@botmesh/mcp</code>, <code>eslint-plugin-botmesh</code> and <code>create-botmesh</code>. All 36 are on npm. Ten of them were first published during the alpha (<code>core</code>, <code>baileys</code>, <code>meta</code>, <code>telegram</code>, <code>sqlite-store</code>, <code>redis-store</code>, <code>ai</code>, <code>http</code>, <code>graph-core</code> and <code>create-botmesh</code>); the other 26 shipped for the first time with the beta. Some pages also describe packages that live only in the <a href="https://github.com/andresayac/botmesh/tree/main/packages" target="_blank" rel="noreferrer">repository</a> for now (the TikTok channel, <code>@botmesh/manager</code>, the sandbox…). Each of those pages says so. Plan a production deployment on the published ones.</p><h2 id="before-each-release-of-your-bot" tabindex="-1">Before each release of your bot <a class="header-anchor" href="#before-each-release-of-your-bot" aria-label="Permalink to &quot;Before each release of your bot&quot;">​</a></h2><ul><li>Tests pass with <code>createTestBot</code> / <code>MockProvider</code> (<a href="./testing">Testing</a>).</li><li>The store files or databases are backed up <strong>before</strong> upgrading <code>@botmesh/sqlite-store</code>: a newer schema version cannot be opened by an older release (<a href="./store#schema-versions-and-upgrades">Schema versions</a>).</li><li>With replicas, every replica runs a version that understands the options you turn on (for example <code>coordination.handover.flows: &#39;forward&#39;</code>).</li></ul>',22)])])}const m=o(s,[["render",d]]);export{p as __pageData,m as default};
